import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast paths for very early rounds
    if n < 3:
        return 'C'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]

    # compute opponent statistics
    opp_d = 0
    for x in opp:
        if x == 'D':
            opp_d += 1
    opp_c = n - opp_d
    opp_rate = opp_d / float(n)

    my_d = 0
    for x in own:
        if x == 'D':
            my_d += 1

    # current opponent defection streak
    ostreak = 0
    for x in reversed(opp):
        if x == 'D':
            ostreak += 1
        else:
            break

    # current own defection streak
    mstreak = 0
    for x in reversed(own):
        if x == 'D':
            mstreak += 1
        else:
            break

    # recent windows
    r = 8 if n >= 8 else n
    recent_opp_d = 0
    for i in range(n - r, n):
        if opp[i] == 'D':
            recent_opp_d += 1
    recent_opp_c = r - recent_opp_d

    r2 = 4 if n >= 4 else n
    r4_d = 0
    for i in range(n - r2, n):
        if opp[i] == 'D':
            r4_d += 1

    # Endgame: exploit the last couple rounds
    rem = 100 - n
    if rem <= 1:
        return 'D'
    if rem == 2:
        # slightly softer: defect unless opponent has been extremely cooperative
        if opp_rate <= 0.05 and recent_opp_d == 0:
            return 'D'
        return 'D'

    # Very hostile opponent: defect almost always, rare probe
    if opp_rate >= 0.6:
        if ostreak == 0 and recent_opp_d == 0 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Sustained defection: punish but avoid infinite DD lock-in
    if ostreak >= 3:
        # If we've already been defecting repeatedly, occasionally try C to reset
        if mstreak >= 3:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just defected (streak 1 or 2)
    if ostreak > 0:
        # Two in a row: retaliate
        if ostreak >= 2:
            return 'D'
        # Single defection: proportional response
        if opp_rate < 0.15:
            # mostly cooperative: retaliate once but be ready to forgive
            if mstreak >= 1:
                # we already retaliated; return to cooperation
                return 'C'
            return 'D'
        if opp_rate < 0.4:
            # moderate: retaliate this turn, then see
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        return 'D'

    # Opponent just cooperated (ostreak == 0)
    # If opponent has been extremely defection-heavy overall but just cooperated, test.
    if opp_rate >= 0.4:
        # grudge mode but accept cooperation when it comes
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Opponent has not defected recently. Decide whether to cooperate or exploit.
    # Against a sustained cooperator (no defections or rare), exploit occasionally
    # but not enough to trigger a long punishment phase.
    if opp_d == 0:
        # Pure cooperator detected. Extract value while staying safe.
        # Early: cooperate to build trust. Mid: mix. Late: defect more.
        if n < 6:
            return 'C'
        if rem <= 6:
            return 'D'
        # Mix: mostly C with occasional D probes to gather exploitation value.
        # But avoid provoking if opponent is TFT-like: only defect when we can
        # afford retaliation (i.e., we haven't defected recently).
        if mstreak == 0:
            if rng.random() < 0.28:
                return 'D'
            return 'C'
        else:
            # We defected recently; return to cooperation to avoid punishment
            if mstreak >= 2:
                return 'C'
            if rng.random() < 0.15:
                return 'D'
            return 'C'

    # Opponent has defected at least once historically, but not recently.
    # This is the "recovering cooperative" regime.
    # If we have been exploiting too much, offer cooperation to reset.
    if mstreak >= 2:
        return 'C'

    # If opponent cooperation rate high and no recent defections, cooperate mostly,
    # with rare stealth defection.
    if opp_rate <= 0.12 and recent_opp_d == 0:
        if r4_d == 0 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Moderate opponent: cooperate but retaliate if they defected recently.
    if recent_opp_d >= 2:
        return 'D'
    if recent_opp_d == 1:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Mostly cooperate against moderately cooperative opponents
    if rng.random() < 0.08:
        return 'D'
    return 'C'
